 =CASE t->>'source'WHEN'ar'THEN'579111e98e7fcb7df64d9fb0ccab96a0'WHEN'newar'THEN'576047ef4fd2bb64dbb3eb29ca349a41'WHEN'kb'THEN'f3f92c17b5ecd79604f5e530960e0c22'END
